def equation(eps, T, params):
    p = params
    L = np.log(eps)
    return (p[0] + p[1]*T + p[2]*T**2 + p[3]*(1-np.exp(-(p[4]+p[5]*T)*eps))*(1+p[6]*T)
            + p[7]*L/eps + p[8]*L**3 + p[9]*L/np.sqrt(eps))
